import { isBusy } from '../state.js';
import { esc, field, formatUTC, header, icon, seconds } from '../components/ui.js';
function progressPanel(s) {
    const busy = isBusy(s);
    return `<div class="processing-panel ${busy ? 'is-processing' : ''}"><div class="processing-title"><span class="${busy ? 'spinner' : 'status-dot'}"></span><strong id="progress-text">${esc(s.progress.text)}</strong><span id="progress-percent" class="mono">${Math.round(s.progress.progress * 100)}%</span></div><div class="progress-track"><i id="progress-bar" style="width:${s.progress.progress * 100}%"></i></div><div class="processing-footer"><span>${icon('cpu')}Lokal beregning · din video sendes ikke</span>${busy ? `<button data-action="cancel" class="text-button">Annuller</button>` : '<span class="mono">ENGINE / 0.1</span>'}</div></div>`;
}
function mediaPanel(s) {
    const isAudio = s.file?.type.startsWith('audio/') || /\.(wav|mp3|m4a|ogg|flac|aac)$/i.test(s.file?.name || '');
    return `<div class="media-panel panel"><div class="panel-heading"><span>01 / DIN OPTAGELSE</span><span class="pill">${s.demo ? 'SYNTETISK DEMO' : 'LOKAL FIL'}</span></div><div class="video-frame ${isAudio ? 'audio-frame' : ''}">${isAudio ? `${icon('wave')}<audio src="${esc(s.blobUrl)}" controls preload="metadata"></audio>` : `<video src="${esc(s.blobUrl)}" controls playsinline preload="metadata" aria-label="Din valgte video"></video>`}<span class="video-private">${icon('lock')}Kun på din enhed</span></div><div class="file-info"><span class="file-icon">${icon('file')}</span><div><strong title="${esc(s.file?.name)}">${esc(s.file?.name)}</strong><small>${s.file ? (s.file.size / 1024 / 1024).toFixed(1) : '0'} MB${s.analysis ? ` · ${seconds(s.analysis.duration)}` : ''} · ${esc(s.file?.type || 'Mediefil')}</small></div><button class="icon-button" data-action="upload" aria-label="Vælg en anden fil" ${isBusy(s) ? 'disabled' : ''}>${icon('reset')}</button></div>${s.decoded ? `<div class="decoded-note">${icon('check')}${esc(s.decoded.method)}</div>` : ''}</div>`;
}
function signalPanel(s) {
    const a = s.analysis;
    return `<div class="signal-panel panel"><div class="panel-heading"><span>02 / SPEKTROGRAM</span><span class="pill ${a ? 'lime' : ''}">${a ? `${a.tracks.length} tonale spor` : 'Afventer måling'}</span></div><div class="lab-spectrum"><canvas id="lab-spectrum" aria-label="Spektrogram af den valgte optagelse"></canvas>${!a ? `<div class="spectrum-placeholder">${s.waveform ? '' : '<span class="signal-loader"></span>'}<strong>${s.waveform ? 'Lydsporet er åbnet' : 'Leder efter lydsporet'}</strong><span>${s.waveform ? 'Bølgeformen nedenfor er fra din fil. Spektrogrammet beregnes nu.' : 'Frekvensdata vises, når de er beregnet.'}</span></div>` : ''}</div><div class="signal-legend">${a ? a.tracks.map((t, i) => `<span><i class="legend-dot track-${i}"></i>${t.id} · ${Math.round(t.driftHz)} Hz fald · ${Math.round(t.coverage * 100)}% spordækning</span>`).join('') || '<span>Ingen brugbare tonale spor. Der vises ikke et opdigtet signal.</span>' : '<span>Ingen simulerede målinger i din analyse.</span>'}</div><div class="waveform-strip"><canvas id="waveform" aria-label="Lydens amplitude over tid"></canvas><span>AMPLITUDE</span></div></div>`;
}
function settings(s) {
    const f = s.form, disabled = isBusy(s) || !s.analysis?.tracks.length;
    return `<section class="search-section" id="search-section"><div class="section-heading compact"><div><div class="eyebrow">03 / SÆT RAMMEN</div><h2>Giv signalet <em>kontekst.</em></h2><p>Optagelsestid og søgeområde er dine oplysninger — ikke noget, appen har fundet.</p></div><button class="btn btn-secondary btn-small" data-action="import" ${isBusy(s) ? 'disabled' : ''}>${icon('upload')}Importér flydata</button></div><form id="search-form" class="search-form"><div class="form-main"><div class="form-grid">${field('Optagelsens starttid · UTC', 'date', f.date, 'type="datetime-local" step="1" required', 'Brug original optagelsestid. Filens ændringsdato bruges ikke.')}
<label class="field"><span>Søgeradius</span><select name="radius">${[3, 6, 10, 25, 50].map(v => `<option value="${v}" ${f.radius === String(v) ? 'selected' : ''}>${v} km</option>`).join('')}</select><small>Afgrænset søgning — ikke et globalt opslag.</small></label></div><div class="region-title"><strong>Centrum for søgeområdet</strong><div class="preset-chips"><button type="button" data-preset="cph">København</button><button type="button" data-preset="aar">Aarhus</button><button type="button" data-preset="ber">Berlin</button></div></div><div class="form-grid">${field('Breddegrad', 'lat', f.lat, 'type="number" step="any" min="-80" max="80" placeholder="55.676" required')}${field('Længdegrad', 'lon', f.lon, 'type="number" step="any" min="-180" max="180" placeholder="12.568" required')}</div>
<details class="advanced"><summary>${icon('settings')}Avancerede parametre${icon('chevron')}</summary><div class="form-grid three"><label class="field"><span>Usikkerhed i kameratid</span><select name="clock">${[0, 10, 30, 60].map(v => `<option value="${v}" ${f.clock === String(v) ? 'selected' : ''}>${v === 0 ? 'Præcis tid' : `±${v} sekunder`}</option>`).join('')}</select></label>${field('Mikrofonhøjde · m MSL', 'altitude', f.altitude, 'type="number" step="1" min="-400" max="9000" required')}${field('Lydens hastighed · m/s', 'sound', f.sound, 'type="number" step="0.1" min="300" max="370" required')}</div><p class="small-print">Højden er over middelvandstand, ikke over gulvet. Standard 343 m/s er en tilnærmelse. Modellen korrigerer ikke for vind eller atmosfærisk brydning.</p></details></div>
<aside class="data-sidebar"><div class="data-source-heading">${icon('layers')}<div><strong>${s.dataset ? 'Flydata er klar' : 'Historiske flydata'}</strong><span>${s.dataset ? `${s.dataset.flights.length} flybaner indlæst` : 'adsb.aero / adsb.lol'}</span></div></div>${s.dataset ? `<div class="dataset-loaded"><span class="pill ${s.dataset.synthetic ? 'amber' : 'lime'}">${s.dataset.synthetic ? 'SYNTETISK TESTDATA' : 'LOKALT INDLÆST'}</span><p>${esc(s.dataset.source)}</p><small>${esc(s.dataset.license)}</small><button type="button" class="text-button" data-action="clear-data">Fjern datasæt</button></div>` : `<p>Appen kontrollerer arkivets datoperiode og henter ét afgrænset udsnit. Mangler data, kan du importere en lokal fil.</p><label class="checkbox-field"><input name="network" type="checkbox" ${s.network ? 'checked' : ''}><span>Tillad at søgeområde og tidsinterval sendes til adsb.aero. <small>Din video og lyd sendes aldrig.</small></span></label>`}<label class="checkbox-field consent-field"><input type="checkbox" name="consent" ${s.consent ? 'checked' : ''}><span>Det er min egen optagelse, eller jeg har tilladelse til at undersøge den.</span></label><button class="btn btn-primary btn-full" type="submit" ${disabled ? 'disabled' : ''}>${icon('search')}${s.dataset ? 'Sammenlign med flydata' : 'Hent flydata og søg'}${icon('arrow')}</button><small class="data-note">Ingen sikker præcision. Ingen automatisk adresse.</small></aside></form></section>`;
}
function results(s) {
    const r = s.result, candidate = r.candidates[s.selected], a = s.analysis, config = s.config, good = r.candidates.filter(c => c.accepted).length, synthetic = s.demo || s.dataset?.synthetic;
    return `<section class="results-section" id="results"><div class="section-heading compact"><div><div class="eyebrow">04 / RESULTAT · ${synthetic ? 'SYNTETISK TEST' : 'EKSPERIMENTEL MODEL'}</div><h2>${good ? 'Et muligt <em>spor.</em>' : 'Intet pålideligt <em>match.</em>'}</h2><p>${good ? 'Disse kandidater passer til modellens kriterier. De er ikke bekræftede optagelsessteder.' : 'Ingen kandidat bestod kriterierne. Et lavt fejlmål alene er ikke bevis for en placering.'}</p></div><button class="btn btn-secondary" data-action="report">${icon('download')}Eksportér rapport</button></div>
<div class="result-status ${good ? '' : 'warning'}">${icon(good ? 'info' : 'search')}<span>${synthetic ? '<strong>Syntetisk testdata.</strong> Resultatet tester kun kodeforløbet — ikke præcisionen på virkelige videoer.' : good > 1 ? '<strong>Flere mulige områder.</strong> Data peger ikke entydigt på ét sted.' : good ? '<strong>Eksperimentel hypotese.</strong> Modellen er ikke kalibreret til at give en sikker adresse eller sandsynlighed.' : '<strong>Ingen konklusion.</strong> De bedst passende beregninger vises kun til inspektion.'}</span></div>
<div class="result-metrics"><div><span>LAVEST MODELFEJL</span><strong>${candidate ? (candidate.misfit * 100).toFixed(2) : '—'}<small>${candidate ? '%' : ''}</small></strong><p>Relativ frekvens-RMSE, ikke sikkerhed</p></div><div><span>MATCHENDE FLYBANER</span><strong>${candidate?.matchedFlights || 0}<small>/ ${s.dataset?.flights.length || 0}</small></strong><p>Separate fly-id’er i bedste tilpasning</p></div><div><span>AFSØGTE HYPOTESER</span><strong>${r.tested.toLocaleString('da-DK')}</strong><p>Positioner × tidsjusteringer</p></div><div><span>LOKAL GRIDAFSTAND</span><strong>${candidate ? Math.round(candidate.gridSpacingM) : '—'}<small>${candidate ? 'm' : ''}</small></strong><p>Beregningsnet — ikke fejlradius</p></div></div>
<div class="result-workspace"><div class="result-map" id="result-map"></div><aside class="candidate-sidebar"><div class="panel-heading"><span>KANDIDATOMRÅDER</span><span class="mono">${String(r.candidates.length).padStart(2, '0')}</span></div>${r.candidates.length ? r.candidates.map((c, i) => `<button class="candidate-card ${s.selected === i ? 'selected' : ''}" data-candidate="${i}"><span class="candidate-index">${String(i + 1).padStart(2, '0')}</span><span class="candidate-content"><strong>${c.accepted ? 'Muligt kandidatområde' : 'Ikke godkendt af modellen'}</strong><span class="mono">${Math.abs(c.lat).toFixed(4)}° ${c.lat >= 0 ? 'N' : 'S'} · ${Math.abs(c.lon).toFixed(4)}° ${c.lon >= 0 ? 'E' : 'W'}</span><small>${(c.misfit * 100).toFixed(2)}% modelfejl · ${c.matchedFlights} flybane${c.matchedFlights === 1 ? '' : 'r'}</small></span>${icon('chevron')}</button>`).join('') : `<div class="empty-candidates">${icon('search')}Ingen beregnelige kandidater. Kontrollér, at lydens tid og flydata overlapper.</div>`}<div class="candidate-note">${icon('info')}Kortnåle repræsenterer de bedst undersøgte gridpunkter. Ikke adresser eller statistiske sikkerhedsområder.</div><div class="time-box"><span>${icon('clock')}INDTASTET OPTAGELSESTID</span><strong>${formatUTC(config.startTime)}</strong><small>Modeljustering: ${candidate ? `${candidate.offset >= 0 ? '+' : ''}${candidate.offset.toFixed(2)} s` : '—'}<br>Tidspunktet er ikke fundet uafhængigt fra lyden.</small></div></aside></div>
<div class="result-detail-grid"><div class="panel fit-panel"><div class="panel-heading"><span>OBSERVATION MOD MODEL</span><span class="small-print">Stiplet hvid = forudsagt frekvens</span></div><canvas id="result-spectrum" aria-label="Målte frekvensspor sammenlignet med modellens forudsagte kurver"></canvas><div class="table-scroll"><table><thead><tr><th>Spor</th><th>Fly / kaldesignal</th><th>Est. kildetone</th><th>Modelfejl</th></tr></thead><tbody>${candidate?.matches.map(m => `<tr><td>${esc(m.trackId)}</td><td>${esc(m.callsign)}<small>${esc(m.flightId)}</small></td><td>${m.sourceHz.toFixed(1)} Hz</td><td>${(m.relativeRmse * 100).toFixed(2)}%</td></tr>`).join('') || '<tr><td colspan="4">Ingen tilgængelige modelkurver.</td></tr>'}</tbody></table></div></div><div class="panel interpretation"><div class="eyebrow">LÆS RESULTATET RIGTIGT</div><h3>Et signal er<br>ikke et <em>bevis.</em></h3><p>${a.tracks.length} sporede toner blev sammenlignet med ${s.dataset?.flights.length || 0} flybaner inden for ${config.radiusKm} km af dit valgte centrum.</p><p>Modelfejlen måler afstanden mellem observerede og beregnede frekvenser. Den fortæller ikke, hvor sandsynligt stedet er, eller hvor mange meter resultatet rammer ved siden af.</p><a class="text-link" href="#/method">Læs modellens forudsætninger ${icon('diagonal')}</a><div class="source-credit">Datakilde: ${esc(s.dataset?.source)}<br>Licens: ${esc(s.dataset?.license)}${s.dataset?.fetchedAt ? `<br>Hentet: ${esc(s.dataset.fetchedAt)}` : ''}</div></div></div>
<details class="warnings-box"><summary>${icon('info')}Forbehold, datakvalitet og diagnose${icon('chevron')}</summary><ul>${[...r.warnings, ...(s.dataset?.warnings || []), ...a.warnings, ...(s.decoded?.warnings || [])].map(w => `<li>${esc(w)}</li>`).join('')}</ul><p>Beregningsversion 0.1.0 · ${r.elapsedMs < 1000 ? `${Math.round(r.elapsedMs)} ms` : `${(r.elapsedMs / 1000).toFixed(1)} s`} · stationær mikrofon · ensartet atmosfære · maks. 30 sekunders interpolationsgab.</p></details><div class="result-actions"><button class="btn btn-primary" data-action="upload">${icon('upload')}Undersøg en ny optagelse</button><button class="btn btn-secondary" data-action="reconfigure">${icon('settings')}Justér søgningen</button></div></section>`;
}
export function labPage(s) {
    const active = s.result ? 4 : s.analysis ? 3 : s.file ? 2 : 1;
    return `${header(true)}<main class="lab-page page-width" id="main"><div class="lab-topline"><a href="#/" class="back-link">${icon('back')}Forside</a><div class="workspace-label"><span class="status-dot"></span>DIT PRIVATE LYDLABORATORIUM</div><span class="pill">BROWSER / 01</span></div><div class="lab-steps">${['Optagelse', 'Lydanalyse', 'Flydata', 'Resultat'].map((v, i) => `<span class="${active === i + 1 ? 'active' : active > i + 1 ? 'complete' : ''}"><i>${active > i + 1 ? icon('check') : String(i + 1).padStart(2, '0')}</i>${v}</span>`).join('')}</div>
${!s.file ? `<div class="lab-empty"><div class="eyebrow">START MED DIN OPTAGELSE</div><h1>Lad os lytte<br><em>efter et spor.</em></h1><div class="dropzone" id="dropzone" tabindex="0" role="button" aria-label="Vælg eller slip en video- eller lydfil" data-action="upload"><span class="drop-icon">${icon('upload')}</span><h3>Slip en video her</h3><p>eller klik for at vælge en fil på din enhed</p><span class="file-types">MP4 · MOV · WEBM · WAV · MP3</span><small>5–180 sekunder · maks. 150 MB · browserens codecs</small></div><div class="empty-actions"><span>${icon('lock')}Filen bliver i browseren</span><button class="text-link" data-action="demo">Prøv en syntetisk demo ${icon('arrow')}</button></div></div>` : `${s.demo ? '<div class="demo-banner"><span class="pill amber">DEMO</span>Syntetisk video + to simulerede flybaner. Ingen virkelig person eller placering er identificeret.</div>' : ''}<div class="lab-title"><div><div class="eyebrow">SIGNALANALYSE / ${s.result ? 'AFSLUTTET' : s.analysis ? 'KLAR' : 'I GANG'}</div><h1>${s.result ? 'Fra lyd til <em>hypotese.</em>' : s.analysis ? 'Der er noget <em>at se.</em>' : 'Vi ser på <em>lyden.</em>'}</h1></div><span class="pill">${icon('shield')}Privat som standard</span></div>${progressPanel(s)}<div class="analysis-grid">${mediaPanel(s)}${signalPanel(s)}</div>`}
${s.error ? `<div class="error-box" role="alert">${icon('info')}<div><strong>Vi kunne ikke fortsætte</strong><p>${esc(s.error)}</p>${s.canFallback ? '<button class="btn btn-secondary btn-small" data-action="capture">Udtræk under afspilning (lokalt)</button>' : ''}</div></div>` : ''}
${s.result ? results(s) : s.analysis ? settings(s) : ''}<div class="lab-bottom-note">${icon('lock')}Ingen mediefiler gemmes af appen. Luk fanen for at rydde sessionen. <a href="#/privacy">Læs om netværkskald</a></div></main>`;
}
